// Canonical P6 process-stop owner; payload copies are generated by sync-process-stop.py.
import assert from 'node:assert/strict';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

export async function readGatewayStopBudget(source) {
  const filename = path.join(source, 'gateway-shutdown-budget.mjs');
  const policy = await import(pathToFileURL(filename).href);
  const shutdownTimeoutMs = policy.GATEWAY_SHUTDOWN_TIMEOUT_MS;
  const serviceStopTimeoutMs = policy.GATEWAY_SERVICE_STOP_TIMEOUT_MS;
  assert(Number.isSafeInteger(shutdownTimeoutMs) && shutdownTimeoutMs > 0,
    'Source must export a positive GATEWAY_SHUTDOWN_TIMEOUT_MS');
  assert(Number.isSafeInteger(serviceStopTimeoutMs) && serviceStopTimeoutMs >= shutdownTimeoutMs,
    'Source must export a GATEWAY_SERVICE_STOP_TIMEOUT_MS covering shutdown');
  return { source: filename, shutdownTimeoutMs, serviceStopTimeoutMs };
}

const stopping = new WeakMap();
function signalGroup(child, signal) {
  try { process.kill(-child.pid, signal); }
  catch (error) { if (error.code !== 'ESRCH') throw error; }
}
async function exitedWithin(child, timeoutMs) {
  let timer;
  try {
    return await Promise.race([child.done.then(() => true),
      new Promise(resolve => { timer = setTimeout(() => resolve(false), timeoutMs); })]);
  } finally { clearTimeout(timer); }
}

export function stopProcess(child, { graceMs = 10_000, killWaitMs = 5_000 } = {}) {
  if (!child?.pid) return Promise.resolve(null);
  if (stopping.has(child)) return stopping.get(child);
  const operation = (async () => {
    const started = performance.now();
    const receipt = { pid: child.pid, graceMs, killWaitMs, sentTerm: false, forced: false };
    if (child.exitCode === null && child.signalCode === null) {
      signalGroup(child, 'SIGTERM');
      receipt.sentTerm = true;
    }
    receipt.exitObserved = await exitedWithin(child, graceMs);
    if (!receipt.exitObserved) {
      receipt.forced = true;
      signalGroup(child, 'SIGKILL');
      receipt.exitObserved = await exitedWithin(child, killWaitMs);
    }
    return { ...receipt, elapsedMs: performance.now() - started,
      exitCode: child.exitCode, exitSignal: child.signalCode };
  })();
  stopping.set(child, operation);
  return operation;
}

export function shutdownFailure(stops, gatewayExit) {
  if (stops.some(stop => stop.forced || !stop.exitObserved)) return 'Process required forced stop';
  if (gatewayExit && (gatewayExit.code !== 0 || gatewayExit.signal !== null)) {
    return 'Gateway did not exit normally';
  }
  return null;
}

if (import.meta.main) {
  assert.equal(process.argv[2], '--gateway-budget');
  assert.equal(process.argv.length, 4, 'Usage: node process-stop.mjs --gateway-budget SOURCE');
  console.log(JSON.stringify(await readGatewayStopBudget(path.resolve(process.argv[3]))));
}
